// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.prank(actor);
        c = new ERCDDAToken(0, "", "");
        vm.prank(actor);
        c.mintToken(actor, amount);
        address ownerBefore = c.owner();
        bool success;
        vm.prank(actor);
        try c.burn(amount) { success = true; } catch { success = false; }
        assertTrue(success ? c.owner() == ownerBefore : true);
    }
}
